func:
// The caller asks to *define* an inspection; the target status is this
// flow's to decide, never the request's.
msg.targetStatus = "Defined";
msg.allowedFrom = ["Created"];
msg.action = "inspectionDefine";
return msg;

// "Planned" is the reassignment revert: changing the acting inspectors of an
// inspection that already has a plan sends it back to Assigned so the plan is
// regenerated. Mirrors shouldRevertToAssignedOnReassign in compliance_web.
msg.targetStatus = "Assigned";
msg.allowedFrom = ["Defined", "Planned"];
msg.action = "inspectionAssign";
return msg;

var inspectionId = msg.req && msg.req.query && msg.req.query.inspection;
if (!inspectionId) {
    msg.statusCode = 400;
    msg.payload = { success: false, error: "inspection is required" };
    return [null, msg];
}

msg.inspectionId = String(inspectionId);
msg.entity = "Inspection";
msg.entityData = { id: msg.inspectionId };
msg.entitySelect = "select=id,status&";
return [msg, null];

// The state machine, enforced here rather than in the browser. An absent or
// empty status means "Created", the same normalisation the web app applies.
var list = (msg.payload && msg.payload.list) || [];
var inspection = list[0];

if (!inspection) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: "Inspection not found: " + msg.inspectionId };
    return [null, null, msg];
}

var current = inspection.status || "Created";

// Already there: nothing to do, and a success — so it takes its own output
// rather than the error envelope's.
if (current === msg.targetStatus) {
    msg.statusCode = 200;
    msg.payload = {
        success: true,
        inspectionId: msg.inspectionId,
        status: current,
        changed: false
    };
    return [null, msg, null];
}

if (msg.allowedFrom.indexOf(current) === -1) {
    msg.statusCode = 409;
    msg.payload = {
        success: false,
        error: "An inspection at \"" + current + "\" cannot move to \"" +
               msg.targetStatus + "\"; allowed from: " + msg.allowedFrom.join(", ")
    };
    return [null, null, msg];
}

msg.previousStatus = current;
return [msg, null, null];

msg.entity = "Inspection";
msg.entityId = msg.inspectionId;
msg.updateData = { status: msg.targetStatus };
return msg;

// The update subflow reports the upstream status; anything but a success is
// returned as the error envelope rather than as a 200 with a raw body.
var code = Number(msg.statusCode);
if (code === 200 || code === 304) {
    msg.statusCode = 200;
    msg.payload = {
        success: true,
        inspectionId: msg.inspectionId,
        status: msg.targetStatus,
        previousStatus: msg.previousStatus,
        changed: true
    };
    return [msg, null];
}

msg.statusCode = code >= 400 ? code : 502;
msg.payload = {
    success: false,
    error: "The status update was refused upstream for inspection " + msg.inspectionId
};
return [null, msg];

var err = msg.error;
var message = (err && err.message) ? err.message
    : (typeof err === "string" && err) ? err
    : (msg.payload && msg.payload.error) ? msg.payload.error
    : (typeof msg.payload === "string" && msg.payload) ? msg.payload
    : "Request failed";
if (!msg.statusCode || Number(msg.statusCode) < 400) {
    msg.statusCode = 400;
}
msg.payload = { success: false, error: message };
return msg;
